import { tags } from "typia";

/**
 * Time-bucketed payout analytics breakdown entry.
 *
 * Each entry represents aggregated payout-related metrics for a specific
 * reporting period such as a day, week, or month. It is typically used for
 * charting trends and analyzing payout performance over time.
 *
 * The period key is a human-readable or ISO-based label that the frontend can
 * use when plotting the breakdown in chronological order.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IShoppingMallPayoutAnalyticsPeriodBreakdown = {
  /**
   * Identifier for the reporting period represented by this breakdown entry.
   *
   * Common examples include formatted dates like "2025-03-15" for daily
   * buckets, "2025-W11" for weekly buckets, or "2025-03" for monthly buckets,
   * depending on the aggregation strategy chosen in the request.
   */
  periodKey: string;

  /**
   * Start timestamp of the reporting period that this breakdown covers.
   *
   * This value is useful for precise alignment with the analytics time line
   * and may differ from the overall query start when used in multiple
   * buckets.
   */
  from: string & tags.Format<"date-time">;

  /**
   * End timestamp of the reporting period that this breakdown covers.
   *
   * The backend uses this value together with `from` to define the exact
   * record selection window for this bucket, which can be used by charting
   * components for tooltips and labels.
   */
  to: string & tags.Format<"date-time">;

  /**
   * Total gross merchandise amount included in this period bucket.
   *
   * This is derived by aggregating `gross_amount` from
   * `shopping_mall_seller_earnings` for records whose timestamps fall within
   * the period range.
   */
  grossAmount: number;

  /**
   * Total commission amount charged in this period bucket.
   *
   * It is computed from `commission_amount` values in
   * `shopping_mall_seller_earnings` that belong to this period and helps
   * visualize platform revenue over time.
   */
  commissionAmount: number;

  /**
   * Total net earning amount owed to sellers in this period bucket.
   *
   * The value is derived from `net_earning_amount` in
   * `shopping_mall_seller_earnings` and supports trend analysis of seller
   * earnings.
   */
  netEarningAmount: number;

  /**
   * Total amount paid out to sellers in this period bucket.
   *
   * This value is aggregated from `payout_amount` in
   * `shopping_mall_seller_payout_items` for payout items whose paid
   * timestamps fall into the period range.
   */
  paidOutAmount: number;

  /**
   * Total amount still pending payout in this period bucket.
   *
   * The backend computes this by comparing eligible earnings and their
   * associated payout items to determine the outstanding balance within this
   * time slice.
   */
  pendingPayoutAmount: number;
};
